namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class PlanningCurrentRootImportWpfTests
{
    [TestMethod]public Task CurrentApplicationUserImportOrdinaryListEditSaveRestartOpenAndSummary()=>RunSta(async()=>
    {
        EnsureTestApplication();using var source=await PlanningFoundationWpfTests.Fixture.Create();using var current=await PlanningFoundationWpfTests.Fixture.Create();var output=Path.GetFullPath(Environment.GetEnvironmentVariable("KITAO_CURRENT_IMPORT_EVIDENCE")??Path.Combine(current.Root,"current-evidence"));Directory.CreateDirectory(output);var vm=source.Vm;await vm.LoadAsync(source.Id);vm.DocumentTitle="当前根导入合成项目";await vm.NewShotCommand.ExecuteAsync(null);var image=Path.Combine(source.Root,"reference.png");await File.WriteAllBytesAsync(image,PlanningRichFlowFixture.ReferencePng(0));var attachment=Path.Combine(source.Root,"call-sheet.txt");await File.WriteAllTextAsync(attachment,"合成通告单");await vm.AddDocumentReferencesAsync([new(Guid.NewGuid(),ShotReferenceKind.General,ExternalReference:image)],true);await vm.AddAttachmentsAsync([attachment],true);Assert.IsTrue(await vm.FlushAsync());var oldSource=Hash(Path.Combine(source.Planning.StorageRoot,source.Id.ToString("N")+".planning.json"));var imageHash=Hash(image);var fileHash=Hash(attachment);var package=Path.Combine(output,"current-root-synthetic-v1.ptplan");await vm.ExportProjectPackageAsync(package);
        // Existing unrelated ordinary project must survive all imports unchanged.
        await current.Vm.LoadAsync(current.Id);current.Vm.DocumentTitle="原有策划";Assert.IsTrue(await current.Vm.FlushAsync());var oldPath=Path.Combine(current.Planning.StorageRoot,current.Id.ToString("N")+".planning.json");var oldHash=Hash(oldPath);
        var dialogs=new Dialogs{File=package};var imported=new PlanningCenterViewModel(current.Projects,current.Bookings,dialogs,current.Shots,current.Planning);dialogs.Answers.Enqueue(true);await imported.ImportCurrentProjectPackageCommand.ExecuteAsync(null);Assert.IsNull(imported.ImportedPackageRoot,"Current import must not switch to independent root");Assert.AreEqual(source.Id,imported.ProjectId);StringAssert.Contains(dialogs.Messages.First(x=>x.Contains("将写入数据库")),current.Planning.StorageRoot);StringAssert.Contains(dialogs.Messages.First(x=>x.Contains("将写入数据库")),"current");
        await imported.ShowOverviewCommand.ExecuteAsync(null);var card=imported.PlanningProjects.Single(p=>p.ProjectId==source.Id);Assert.AreEqual(source.Id,card.ProjectId);await imported.OpenPlanningProjectCommand.ExecuteAsync(card);imported.DocumentTitle="导入后普通编辑保存";imported.DocumentCustomBody="当前应用数据根正文";Assert.IsTrue(await imported.FlushAsync());
        var view=new PlanningCenterView{DataContext=imported};view.Measure(new Size(1100,800));view.Arrange(new Rect(0,0,1100,800));view.UpdateLayout();view.DataContext=null;
        var restarted=current.NewVm();await restarted.ShowOverviewCommand.ExecuteAsync(null);Assert.IsTrue(restarted.PlanningProjects.Any(x=>x.ProjectId==source.Id));await restarted.OpenPlanningProjectCommand.ExecuteAsync(restarted.PlanningProjects.Single(x=>x.ProjectId==source.Id));Assert.AreEqual("导入后普通编辑保存",restarted.DocumentTitle);Assert.AreEqual("当前应用数据根正文",restarted.DocumentCustomBody);Assert.IsNotNull(await restarted.ResolveOriginalAsync(restarted.AllProjectReferences.Single()));Assert.AreEqual(imageHash,Hash((await restarted.ResolveOriginalAsync(restarted.AllProjectReferences.Single()))!));Assert.AreEqual(fileHash,Hash(restarted.ResolveAttachmentPath(restarted.Attachments.Single())!));
        var summary=Path.Combine(output,"current-root-summary.docx");Assert.IsNotNull(await restarted.ExportPlanningSummaryDocxAsync(summary));using(var doc=WordprocessingDocument.Open(summary,false)){Assert.IsFalse(new OpenXmlValidator().Validate(doc).Any());StringAssert.Contains(doc.MainDocumentPart!.Document.InnerText,"call-sheet.txt");}
        dialogs.Answers.Enqueue(true);await imported.ImportCurrentProjectPackageCommand.ExecuteAsync(null);Assert.IsTrue(dialogs.Errors.Any(x=>x.Contains("项目ID冲突")));Assert.AreEqual(oldHash,Hash(oldPath));Assert.AreEqual(oldSource,Hash(Path.Combine(source.Planning.StorageRoot,source.Id.ToString("N")+".planning.json")));Assert.AreEqual(imageHash,Hash(image));Assert.AreEqual(fileHash,Hash(attachment));
        await File.WriteAllTextAsync(Path.Combine(output,"RESULT.json"),JsonSerializer.Serialize(new{project=source.Id,document=(await current.Planning.LoadAsync(source.Id)).Document!.Package!.DocumentId,package,packageHash=Hash(package),sourceImageHash=imageHash,sourceAttachmentHash=fileHash,sourcePlanningHash=oldSource,oldCurrentProjectHash=oldHash,ordinaryList=true,editedSavedRestarted=true,currentPlanningRoot=current.Planning.StorageRoot,currentShotRoot=current.Shots.StorageRoot,summary,summaryHash=Hash(summary),scope="Production current-app command with synthetic dialog decisions, real database/files and WPF layout; NOT native mouse or WPS"},new JsonSerializerOptions{WriteIndented=true}));Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
    });
    static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
    sealed class Dialogs:IDialogService
    {public string? File;public Queue<bool> Answers=new();public List<string> Messages=[],Errors=[];public IReadOnlyList<string> ChooseFiles(string title,string filter,bool multi)=>File is null?[]:[File];public bool Confirm(string message,string title){Messages.Add(message);return Answers.Dequeue();}public void ShowInfo(string message)=>Messages.Add(message);public void ShowError(string message)=>Errors.Add(message);public string? ChooseFolder(string title,string? initialDirectory=null)=>throw new InvalidOperationException("Current import must not ask for another data root");public string? ChooseSaveFile(string title,string filter,string ext,string? name=null)=>null;public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string> ids)=>ids;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RawFileEntry? ChooseRawCandidate(IReadOnlyList<RawFileEntry> c)=>null;public bool ShowMediaDetails(MediaSelectionItem i,bool b)=>false;public void RevealFile(string path)=>Assert.IsTrue(System.IO.File.Exists(path));}
}
